mapper.select:
select odb.*,cc.con_name conName from osm_design_briefing odb left join Con_Contract cc  on odb.con_id=cc.Con_Id

    
        and odb.title like concat('%',#{params.title},'%')
    
    
        and odb.code like concat('%',#{params.code},'%')
    
    
        and cc.con_id = #{params.conId}
    
    
        and cc.con_name like concat('%',#{params.conName},'%')
    
    
        and odb.using_seals = #{params.usingSeals}
    
    
        and odb.seals_type = #{params.sealsType}
    
    
        and odb.state = #{params.state}
    
    
        and odb.handler_user_name like concat('%',#{params.handlerUserName},'%')
    
    
        and odb.create_uname like concat('%',#{params.createUname},'%')
